/* Interactions verified in the reference site. The app remains entirely local. */
'use strict';
const imageModels=['即梦 ImageMax 1.0','Seedream 5.0 Pro','Seedream 5.0 Flash','图片美学模型 V8.2','Seedream 5.0 Lite','Seedream 4.7','Seedream 4.6','Seedream 4.5','Seedream 4.1','Seedream 4.0','Seedream 3.1','Seedream 3.0'];
const observedModels={image:imageModels,video:['即梦 Seedance 2.0 mini','Seedance 2.0','Seedance 1.5 Pro'],music:['SeedMusic 1.0 Preview'],audio:['SeedAudio 1.0'],avatar:['快速模式','标准模式'],motion:['生动','标准']};
for(const m of modes)m.models=observedModels[m.id];
modes[0].cost=8;
const ratios=['智能','1:1','9:16','16:9','3:4','4:3','2:3','3:2','9:21','21:9'];
const oldSetMode=setMode,oldPreview=preview,oldMedia=media,oldGenerate=generate,oldReedit=reedit,oldCloseModal=closeModal;
let selectedAssets=new Set(),bulkMode=false,assetAdvanced={liked:false,upscaled:false,resolutions:[],ratios:[]},assetPanel='',editingSession=null,previewIndex=null,voiceTab='all',voiceQuery='',voiceGender='',voiceAge='',voiceLanguage='',voiceTrait='',referenceSlot='reference',pendingSubjectName='';
const voices=[{id:'warm',name:'温柔女声',gender:'女',age:'青年',language:'普通话',trait:'温柔'},{id:'deep',name:'磁性男声',gender:'男',age:'青年',language:'普通话',trait:'磁性'},{id:'child',name:'明亮童声',gender:'男',age:'儿童',language:'普通话',trait:'活泼'},{id:'elder',name:'和蔼奶奶',gender:'女',age:'老年',language:'普通话',trait:'温柔'},{id:'narrator',name:'沉稳解说',gender:'男',age:'中年',language:'普通话',trait:'沉稳'},{id:'english',name:'清晰英文',gender:'女',age:'青年',language:'英语',trait:'清晰'}];
const motionTemplates=[{id:'wave',name:'轻轻挥手',duration:8,emoji:'👋'},{id:'turn',name:'回身微笑',duration:6,emoji:'↶'},{id:'dance',name:'轻快律动',duration:9,emoji:'♫'},{id:'walk',name:'自然走来',duration:5,emoji:'🚶'}];
function normalizeDraft(d){for(const [key,value] of Object.entries({audioMode:'全能配音',referenceMode:'全能参考',musicSmart:true,musicSeconds:120,videoSeconds:5,spoken:'',actionDescription:'',voice:'温柔女声',motionTemplate:'',attachments:[],modeDrafts:{}}))if(d[key]===undefined)d[key]=structuredClone(value);if(d.model==='Seedream 5.0')d.model='Seedream 5.0 Pro';return d;}
state.voiceLikes||=[];state.editDrafts||=[];state.sessions.forEach(s=>normalizeDraft(s.draft));
function previewBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function isReady(d){if(pending)return false;if(d.mode==='motion')return !!d.refs.length&&!!(d.motionTemplate||d.attachments.some(a=>a.slot==='motion'));if(d.mode==='avatar')return !!d.refs.length&&!!(d.spoken.trim()||d.attachments.some(a=>a.slot==='speech'));return !!d.prompt.trim();}
function updateReady(){if($('#generate'))$('#generate').disabled=!isReady(normalizeDraft(draft()));}
function renderReferenceThumb(ref,index,attachment=false){return `<div class="reference-thumb">${ref.type?.startsWith('audio/')?icon('audio'):ref.type?.startsWith('video/')?icon('video'):`<img src="${esc(ref.src)}" alt="${esc(ref.name||'参考图')}">`}<span class="ref-name">${esc(ref.name||'参考图')}</span><button data-action="${attachment?'remove-attachment':'remove-ref'}" data-index="${index}" aria-label="移除 ${esc(ref.name||'参考图')}">×</button></div>`;}
syncComposer=function(){
 const d=normalizeDraft(draft()),m=mode(),row=$('.prompt-row'),referenceStrip=$('#reference-strip');
 if(row.dataset.mode!==d.mode){row.dataset.mode=d.mode;row.innerHTML=`<div class="input-slots"></div><div class="prompt-fields"><textarea id="prompt" rows="2" aria-label="创作描述"></textarea><div id="avatar-fields" hidden><label>说话内容<textarea id="spoken" placeholder="请输入你希望角色说出的内容" aria-label="说话内容"></textarea></label><label>动作描述 <small>可选</small><textarea id="action-description" placeholder="添加动作或镜头语言，例如：镜头推进，角色微笑着挥手" aria-label="动作描述"></textarea></label></div></div>`;}
 if(referenceStrip.parentElement!==row)row.prepend(referenceStrip);
 const special=['avatar','motion'].includes(d.mode),slot=(label,action,svg)=>`<button class="upload-tile" data-action="${action}" title="${label}">${icon(svg)}<span>${label}</span></button>`;
 $('.input-slots').innerHTML=d.mode==='motion'?slot('角色','pick-role','person')+slot('动作','pick-motion','video'):d.mode==='avatar'?slot('角色','pick-role','person')+slot('音色','voice-library','audio'):d.mode==='music'?'':slot(d.mode==='video'?'参考内容':'参考素材','reference-options','plus');
 $('#prompt').hidden=d.mode==='avatar';$('#prompt').disabled=d.mode==='motion';$('#avatar-fields').hidden=d.mode!=='avatar';$('#prompt').value=d.prompt;
 $('#prompt').placeholder=d.mode==='motion'?'上传角色图片后，选择动作模板或参考视频':d.mode==='music'?'描述音乐风格、情绪、乐器与人声，例如：舒缓的钢琴，雨天氛围…':d.mode==='audio'?(d.audioMode==='文本朗读'?'请输入你想生成的说话内容':'输入台词并描述声音，可上传参考音频，引用多个音色，用时间戳编排人声、音效与配乐…'):d.mode==='video'?'上传最多 12 个参考素材，输入文字或 @ 引用图片、视频和音频，描述镜头与互动…':'上传参考图、输入文字或 @ 主体，描述你想生成的图片…';
 if(d.mode==='avatar'){$('#spoken').value=d.spoken;$('#action-description').value=d.actionDescription;}
 const params=$('.param-group');params.innerHTML=`<button class="param mode-param" data-menu="mode">${icon(m.icon)}<span>${m.name}</span>${icon('chevron','chev')}</button><span class="param-divider"></span><button class="param" data-menu="model"><span class="cube">◇</span><span>${esc(d.model)}</span></button>${d.mode==='video'?`<button class="param" data-menu="reference-mode">${esc(d.referenceMode)} ${icon('chevron','chev')}</button>`:''}${d.mode==='audio'?`<button class="param" data-menu="audio-mode">${esc(d.audioMode)} ${icon('chevron','chev')}</button>`:''}${['image','video'].includes(d.mode)?`<button class="param" data-menu="format"><span class="ratio-icon"></span><span>${esc(d.ratio==='智能'?'智能比例':d.ratio)} · ${esc(d.resolution)}</span></button><button class="param" data-menu="count">▥ ${d.count} ${m.unit}</button>`:''}${['video','music'].includes(d.mode)?`<button class="param" data-menu="duration">${d.mode==='music'&&d.musicSmart?'智能时长':(d.mode==='music'?d.musicSeconds:d.videoSeconds)+'s'}</button>`:''}${['audio','avatar'].includes(d.mode)?`<button class="param" data-action="voice-library">${icon('audio')}${d.voice==='温柔女声'?'音色库':'<span data-user-content>'+esc(d.voice)+'</span>'}</button>`:''}${d.mode==='avatar'?`<button class="param" data-action="upload-speech">${icon('plus')}上传音频</button>`:''}${d.mode==='image'?`<button class="icon-btn" data-action="insert-quotes" title="添加画面文字" aria-label="添加画面文字">T„</button>`:''}${['image','video','audio'].includes(d.mode)?'<button class="icon-btn" data-action="mention" title="引用主体" aria-label="引用主体">@</button>':''}`;
 $('#reference-strip').innerHTML=d.refs.map((r,i)=>renderReferenceThumb(r,i)).join('')+d.attachments.map((r,i)=>renderReferenceThumb(r,i,true)).join('')+(d.motionTemplate?`<button class="template-chip" data-action="pick-motion">${icon('video')}${esc(motionTemplates.find(t=>t.id===d.motionTemplate)?.name||d.motionTemplate)} <span data-action="remove-motion">×</span></button>`:'');
 $('#composer-hint').textContent=m.hint;$('#cost').textContent=m.cost;$('#cost-unit').textContent=` / ${m.unit}`;$('#generate').title=`演示生成，总计 ${m.cost*d.count} 灵感积分`;
 updateReady();
};
setMode=function(id){const d=normalizeDraft(draft());d.modeDrafts[d.mode]={...structuredClone(d),modeDrafts:{}};const prior=d.modeDrafts[id];oldSetMode(id);if(prior)Object.assign(d,prior,{modeDrafts:d.modeDrafts});else{d.model=observedModels[id][id==='image'?1:0];d.count=1;if(id==='image'){d.resolution='2K';d.ratio='智能';}if(id==='video'){d.resolution='720P';d.ratio='16:9';}d.prompt='';d.refs=[];d.attachments=[];}save();syncComposer();};
menu=function(kind){if(openMenu===kind){closeMenu();return;}openMenu=kind;const p=$('#popover'),d=normalizeDraft(draft()),m=mode();p.hidden=false;p.style.width='280px';
 const item=(text,attr,selected,sub='')=>`<button class="menu-item ${selected?'selected':''}" ${attr}><span>${esc(text)}${sub?`<small>${esc(sub)}</small>`:''}</span>${selected?'<span class="check">✓</span>':''}</button>`;
 if(kind==='mode'){p.innerHTML='<div class="popover-title">创作类型</div>'+modes.map(x=>item(x.name,`data-mode="${x.id}"`,d.mode===x.id)).join('');return;}
 if(kind==='model'){p.innerHTML='<div class="popover-title">选择模型 · 仅演示参数</div>'+m.models.map((x,i)=>item(x,`data-model="${esc(x)}"`,x===d.model, d.mode==='image'?['综合生图、设计与图片编辑','商业设计、影视与高密度图文','更快的创作探索','专注美感与艺术表达'][i]||'保留多种创作选择':'切换并保存模型参数')).join('');return;}
 if(kind==='count'){p.style.width='200px';p.innerHTML='<div class="popover-title">选择生成数量</div><div class="choices count-choices">'+[1,2,3,4].map(n=>`<button class="choice ${d.count===n?'selected':''}" data-count="${n}">${n}</button>`).join('')+`</div><p class="helper">${m.cost} 积分/${m.unit} · 合计 ${m.cost*d.count} 演示积分</p>`;return;}
 if(kind==='format'){p.style.width='330px';p.innerHTML=`<div class="format-section"><label>选择比例</label><div class="choices ratio-choices">${ratios.map(r=>`<button class="choice ${r===d.ratio?'selected':''}" data-ratio="${r}">${r}</button>`).join('')}</div></div><div class="format-section"><label>选择分辨率</label><div class="choices">${(d.mode==='image'?['1.5K','2K','4K']:['480P','720P','1080P']).map(v=>`<button class="choice ${d.resolution===v?'selected':''}" data-resolution="${v}">${v}</button>`).join('')}</div><div class="dimension-readout">W <strong>${dimensions(d)[0]}</strong><span>⌁</span> H <strong>${dimensions(d)[1]}</strong><small>PX</small></div></div>`;return;}
 if(kind==='duration'){const music=d.mode==='music',min=music?30:4,max=music?360:15,value=music?d.musicSeconds:d.videoSeconds;p.innerHTML=`<div class="format-section"><label>选择${music?'音乐':'视频'}生成时长</label>${music?`<label class="switch-row">智能时长<input id="music-smart" type="checkbox" ${d.musicSmart?'checked':''}></label>`:''}<div class="duration-value"><strong id="duration-value">${value}</strong><span>秒</span></div><input id="duration-range" type="range" min="${min}" max="${max}" value="${value}" aria-label="时长"><div class="range-labels"><span>${min}s</span><span>${max}s</span></div><label class="number-row">自定义秒数 <input id="duration-number" type="number" min="${min}" max="${max}" value="${value}" aria-label="时长秒数"></label><div class="helper">${music?'智能时长开启时由曲目结构决定长度。':'时长保存在视频创作参数中。'}</div></div>`;return;}
 const entries=kind==='audio-mode'?['全能配音','文本朗读']:['全能参考','首尾帧'];const key=kind==='audio-mode'?'audioMode':'referenceMode';p.innerHTML='<div class="popover-title">'+(kind==='audio-mode'?'配音方式':'参考方式')+'</div>'+entries.map(v=>item(v,`data-draft-key="${key}" data-draft-value="${v}"`,d[key]===v)).join('');
};
function dimensions(d){const edge=({'1.5K':1536,'2K':2048,'4K':4096,'480P':854,'720P':1280,'1080P':1920})[d.resolution]||2048;const [w,h]=(d.ratio==='智能'?'1:1':d.ratio).split(':').map(Number);return w>=h?[edge,Math.round(edge*h/w)]:[Math.round(edge*w/h),edge];}
generate=async function(){const d=normalizeDraft(draft());if(!isReady(d)){toast(d.mode==='motion'?'请先选择角色图片和动作素材':d.mode==='avatar'?'请添加角色和说话内容或音频':'请先输入创作描述');return;}if(d.mode==='avatar')d.prompt=`${d.spoken}${d.actionDescription?'；动作描述：'+d.actionDescription:''}`||'使用上传音频驱动角色';if(d.mode==='motion')d.prompt=`角色动作演示：${motionTemplates.find(t=>t.id===d.motionTemplate)?.name||'参考视频动作'}`;d.duration=d.mode==='music'?(d.musicSmart?'智能时长':d.musicSeconds+'s'):d.videoSeconds+'s';if(!['image','video'].includes(d.mode))d.count=1;await oldGenerate();};
actions.generate=generate;
actions['insert-quotes']=()=>{const p=$('#prompt'),start=p.selectionStart,end=p.selectionEnd;draft().prompt=p.value.slice(0,start)+'“'+p.value.slice(start,end)+'”'+p.value.slice(end);save();syncComposer();p.focus();p.setSelectionRange(start+1,start+1+(end-start));};
actions['reference-options']=()=>{const d=normalizeDraft(draft());modal('添加参考素材',`<div class="reference-actions"><button class="tool-card" data-action="upload-reference">${icon('plus')}<h3>从本地上传</h3><p>${d.mode==='video'?'图片、音频或视频':d.mode==='audio'?'选择音频文件':'选择图片文件'}</p></button><button class="tool-card" data-action="pick-local-asset">${icon('folder')}<h3>从资产选择</h3><p>引用已有作品和上传素材</p></button></div><p class="helper">素材仅保存在此浏览器，不会上传到外部平台。</p>`);};
actions['pick-local-asset']=()=>{const items=state.records.filter(r=>!r.deleted&&r.mode!=='document'&&(draft().mode==='video'||draft().mode==='audio'&&StudioUtils.category(r)==='audio'||['image','upload'].includes(r.mode)));modal('选择参考素材',items.length?`<div class="subject-grid">${items.map(r=>`<button class="subject-pick" data-action="reference-from-asset" data-id="${r.id}">${StudioUtils.category(r)==='image'?`<img src="${esc(r.src)}" alt="">`:icon(StudioUtils.category(r)==='audio'?'audio':'video')}<span>${esc(r.prompt.slice(0,18))}</span></button>`).join('')}</div>`:'<p>暂无可引用的素材，请先上传。</p>');};
actions['reference-from-asset']=el=>{const r=record(el.dataset.id);const d=draft();if(StudioUtils.category(r)==='image')d.refs.push({src:r.src,name:r.prompt,blobKey:r.blobKey});else d.attachments.push({src:r.src,name:r.prompt,type:r.mime||((r.mode==='audio'||r.mode==='music')?'audio/wav':'video/mp4'),blobKey:r.blobKey,slot:referenceSlot});save();closeModal();syncComposer();};
actions['pick-role']=()=>{referenceSlot='role';modal('选择角色',`<div class="reference-actions"><button class="tool-card" data-action="upload-role">${icon('image')}<h3>上传角色图片</h3><p>清晰的正面角色图片效果更好</p></button><button class="tool-card" data-action="mention">${icon('person')}<h3>引用主体</h3><p>选择已保存的专属角色</p></button></div>`);};
actions['upload-role']=()=>upload('role');actions['upload-speech']=()=>upload('speech');
actions['upload-subject']=()=>{pendingSubjectName=$('#subject-name')?.value.trim()||'';upload('subject');};
actions['pick-motion']=()=>modal('选择动作来源',`<div class="motion-library">${motionTemplates.map(t=>`<button class="motion-card ${draft().motionTemplate===t.id?'selected':''}" data-action="select-motion" data-id="${t.id}"><span class="motion-demo ${t.id}">${t.emoji}</span><strong>${t.name}</strong><small>${t.duration}s · 动作示例</small></button>`).join('')}</div>`,`<button class="secondary-btn" data-action="upload-motion">${icon('video')}上传参考视频</button>`);
actions['upload-motion']=()=>upload('motion');actions['select-motion']=el=>{draft().motionTemplate=el.dataset.id;save();closeModal();syncComposer();};actions['remove-motion']=()=>{draft().motionTemplate='';save();syncComposer();};
actions['remove-attachment']=el=>{draft().attachments.splice(Number(el.dataset.index),1);save();syncComposer();};
function voiceLibrary(){const filtered=voices.filter(v=>(voiceTab!=='liked'||state.voiceLikes.includes(v.id))&&(voiceTab!=='mine'||v.mine)&&(!voiceGender||v.gender===voiceGender)&&(!voiceAge||v.age===voiceAge)&&(!voiceLanguage||v.language===voiceLanguage)&&(!voiceTrait||v.trait===voiceTrait||v.traits?.includes(voiceTrait))&&v.name.includes(voiceQuery));modal('音色库',`<div class="tabs voice-tabs">${[['all','全部音色'],['mine','我的音色'],['liked','收藏']].map(([id,t])=>`<button class="tab ${voiceTab===id?'active':''}" data-voice-tab="${id}">${t}</button>`).join('')}</div><div class="voice-filters">${[['gender','性别',['女','男'],voiceGender],['age','年龄',['儿童','青年','中年','老年'],voiceAge],['language','语言',['普通话','英语'],voiceLanguage],['trait','声音特点',['温柔','磁性','活泼','沉稳','清晰'],voiceTrait]].map(([key,label,options,current])=>`<select data-voice-filter="${key}" aria-label="${label}"><option value="">${label}</option>${options.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('')}</select>`).join('')}</div><div class="voice-grid">${filtered.map(v=>`<article class="voice-card"><button class="voice-play" data-action="preview-voice" data-id="${v.id}" aria-label="试听${v.name}">${icon('audio')}</button><strong>${v.name}</strong><small>${v.gender} · ${v.age} · ${v.language}</small><div><button class="secondary-btn" data-action="select-voice" data-id="${v.id}">使用</button><button class="icon-btn ${state.voiceLikes.includes(v.id)?'liked':''}" data-action="like-voice" data-id="${v.id}" aria-label="收藏${v.name}">${icon('heart')}</button></div></article>`).join('')||'<div class="empty small-empty"><p>暂无符合条件的音色</p></div>'}</div><p class="helper">音色为本地演示预设；试听使用设备可用的浏览器语音，不代表真实模型音色。</p>`, '',true);}
actions['voice-library']=voiceLibrary;
actions['select-voice']=el=>{draft().voice=voices.find(v=>v.id===el.dataset.id).name;save();closeModal();syncComposer();};
actions['like-voice']=el=>{const id=el.dataset.id;state.voiceLikes=state.voiceLikes.includes(id)?state.voiceLikes.filter(x=>x!==id):[...state.voiceLikes,id];save();voiceLibrary();};
actions['preview-voice']=el=>{if(!('speechSynthesis'in window)){toast('此浏览器不支持语音试听');return;}speechSynthesis.cancel();const voice=voices.find(v=>v.id===el.dataset.id),u=new SpeechSynthesisUtterance(voice.language==='英语'?'Hello, let your imagination become a story.':'你好，让每一个灵感，都有自己的声音。');u.lang=voice.language==='英语'?'en-US':'zh-CN';u.pitch=voice.gender==='女'?1.2:voice.age==='儿童'?1.4:.85;u.rate=.95;speechSynthesis.speak(u);toast(`正在试听 ${voice.name}（浏览器演示）`);};
const blobUrls=new Map();let mediaDB;
function db(){return mediaDB||=(new Promise((resolve,reject)=>{const request=indexedDB.open('zaomeng-media',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);}));}
async function putBlob(file,key){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function getBlob(key){const database=await db();return new Promise((resolve,reject)=>{const request=database.transaction('files').objectStore('files').get(key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function hydrateMedia(){const drafts=state.sessions.flatMap(s=>[s.draft,...Object.values(s.draft.modeDrafts||{})]);const entries=[...state.records,...state.subjects,...drafts.flatMap(d=>[...(d.refs||[]),...(d.attachments||[])]),...state.records.flatMap(r=>[...(r.refs||[]),...(r.attachments||[])])];for(const r of entries)if(r.blobKey){try{const blob=await getBlob(r.blobKey);if(blob){if(!blobUrls.has(r.blobKey))blobUrls.set(r.blobKey,URL.createObjectURL(blob));r.src=blobUrls.get(r.blobKey);}else r.src='';}catch{r.src='';}}render();}
upload=function(kind){closeModal();uploadKind=kind;referenceSlot=['role','speech','motion'].includes(kind)?kind:'reference';const input=$('#media-file-input');input.value='';input.multiple=!['role','speech','motion','subject'].includes(kind);input.accept=kind==='motion'?'video/*':kind==='speech'?'audio/*':kind==='role'?'image/*':kind==='asset'?'image/*,audio/*,video/*,.txt,.md,.pdf':draft().mode==='video'?'image/*,audio/*,video/*':draft().mode==='audio'?'audio/*':'image/*';input.click();};
const mediaInput=document.createElement('input');mediaInput.type='file';mediaInput.id='media-file-input';mediaInput.hidden=true;document.body.append(mediaInput);
mediaInput.addEventListener('change',async e=>{const files=[...e.target.files];for(const file of files){try{if(file.size>50*1024*1024)throw Error('单个素材请控制在 50MB 以内');const isImage=file.type.startsWith('image/'),isAudio=file.type.startsWith('audio/'),isVideo=file.type.startsWith('video/');if(!isImage&&!isAudio&&!isVideo&&!/\.(pdf|txt|md)$/i.test(file.name))throw Error('暂不支持此素材格式');let src,blobKey;
 if(isImage)src=await readImage(file);else{blobKey=uid();await putBlob(file,blobKey);src=URL.createObjectURL(file);blobUrls.set(blobKey,src);}
 const item={src,blobKey,name:file.name,type:file.type||'text/plain',slot:referenceSlot};const d=normalizeDraft(draft());
 if(uploadKind==='subject')state.subjects.push({id:uid(),name:pendingSubjectName||file.name.replace(/\.[^.]+$/,'').slice(0,20),src,blobKey});
 else if(uploadKind==='asset')state.records.push({id:uid(),session:null,prompt:file.name,src,blobKey,mime:item.type,mode:isImage?'upload':isAudio?'audio':isVideo?'video':'document',upload:true,model:'本地上传',ratio:'原始',created:Date.now(),liked:false});
 else if(isImage){const max=d.mode==='video'?12:6;if(d.refs.length+d.attachments.length>=max)throw Error(`最多添加 ${max} 个参考素材`);if(uploadKind==='role')d.refs=[];d.refs.push(item);}
 else{if(d.refs.length+d.attachments.length>=12)throw Error('最多添加 12 个参考素材');if(['speech','motion'].includes(referenceSlot))d.attachments=d.attachments.filter(a=>a.slot!==referenceSlot);d.attachments.push(item);}
 }catch(error){toast(error.message);return;}}
 save();render();toast('素材已保存在本地浏览器');});
actions['upload-reference']=()=>upload('reference');actions['upload-asset']=()=>upload('asset');
media=function(r,asset=false){if(r.upload&&r.mode==='document')return `<div class="document-cover">${icon('folder')}<span>${esc(r.prompt.split('.').at(-1).toUpperCase())}</span></div>`;if(r.upload&&r.mode==='video')return r.src?`<video src="${esc(r.src)}" ${asset?'preload="metadata"':'controls'}></video>`:'<div class="document-cover">视频文件暂不可用</div>';if(r.upload&&r.mode==='audio')return `<div class="audio-file">${icon('audio')}${asset?`<span>${r.cloud?'音频素材':'本地音频'}</span>`:`<audio controls src="${esc(r.src)}"></audio>`}</div>`;return oldMedia(r,asset);};
getAssets=function(){return StudioUtils.filterAssets(state.records,{...assetAdvanced,type:assetFilter==='liked'?'all':assetFilter,liked:assetFilter==='liked'||assetAdvanced.liked,search:assetSearch,sort:assetSort});};
function selectedVisible(){return getAssets().filter(r=>selectedAssets.has(r.id));}
renderAssets=function(){const items=getAssets(),activeCount=assetAdvanced.ratios.length+assetAdvanced.resolutions.length+Number(assetAdvanced.liked)+Number(assetAdvanced.upscaled);$('#view').innerHTML=header('我的资产','把每一次创作，留在你的灵感库。',`<div class="asset-header-actions"><button class="secondary-btn" data-action="toggle-bulk">${bulkMode?'退出批量':'批量操作'}</button><button class="primary-btn" data-action="upload-asset">${icon('plus')}上传素材</button></div>`)+`<div class="asset-library-tabs"><span class="active">生成历史</span><span>${state.records.filter(r=>r.upload).length} 个上传素材</span></div><div class="filterbar"><div class="tabs">${[['all','全部'],['image','图片'],['video','视频'],['audio','音频'],['document','文档'],['liked','收藏']].map(([id,t])=>`<button class="tab ${assetFilter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="asset-search" value="${esc(assetSearch)}" placeholder="搜索提示词、文件名…" aria-label="搜索资产"></label></div><div class="asset-controls"><button class="secondary-btn ${activeCount?'active-filter':''}" data-action="asset-filter-panel">${icon('tools')}筛选${activeCount?' · '+activeCount:''}</button><button class="secondary-btn" data-action="asset-sort">时间 ${assetSort==='newest'?'近 → 远':'远 → 近'} ${icon('chevron')}</button>${activeCount?'<button class="subtle-button" data-action="clear-filters">清空筛选</button>':''}</div>${assetPanel==='filters'?advancedFilterHTML():''}${bulkMode?`<div class="bulk-bar"><label><input id="select-all-assets" type="checkbox" ${items.length&&selectedVisible().length===items.length?'checked':''}>全选当前结果</label><span id="selection-count">已选择 ${selectedAssets.size} 项</span><button data-action="bulk-like" ${!selectedAssets.size?'disabled':''}>${icon('heart')}收藏</button><button data-action="bulk-download" ${!selectedAssets.size?'disabled':''}>${icon('download')}下载 ZIP</button><button data-action="bulk-delete" ${!selectedAssets.size?'disabled':''}>${icon('close')}删除</button><button data-action="clear-selection">取消选择</button></div>`:''}<div id="asset-results">${assetResults(items)}</div>`;};
const oldAssetCard=assetCard;
assetCard=function(r,explore=false){let html=oldAssetCard(r,explore).replace('class="asset-image"','class="asset-image" role="button" tabindex="0" aria-label="预览作品"');if(bulkMode&&!explore)html=html.replace('<article class="asset-card">',`<article class="asset-card ${selectedAssets.has(r.id)?'is-selected':''}"><label class="asset-select"><input type="checkbox" data-select-asset="${r.id}" aria-label="选择 ${esc(r.prompt.slice(0,20))}" ${selectedAssets.has(r.id)?'checked':''}></label>`);return html;};
assetResults=function(items){if(!items.length)return '<div class="empty">'+icon('folder')+'<h2>没有找到符合条件的内容</h2><p>试试调整筛选条件，或上传新的素材。</p><button class="primary-btn" data-action="clear-filters">清空筛选</button></div>';const groups=new Map();for(const r of items){const key=new Date(r.created).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return `<p class="asset-total">共 ${items.length} 个作品与素材</p>`+[...groups].map(([date,rows])=>`<div class="asset-date">${date}</div><div class="gallery">${rows.map(r=>assetCard(r)).join('')}</div>`).join('');};
function advancedFilterHTML(){const group=(label,key,options)=>`<fieldset><legend>${label}</legend>${options.map(v=>`<label><input type="checkbox" data-asset-advanced="${key}" value="${v}" ${assetAdvanced[key].includes(v)?'checked':''}>${v}</label>`).join('')}</fieldset>`;return `<section class="advanced-filters"><div class="advanced-filter-top"><label><input type="checkbox" data-asset-flag="liked" ${assetAdvanced.liked?'checked':''}>只看收藏</label><label><input type="checkbox" data-asset-flag="upscaled" ${assetAdvanced.upscaled?'checked':''}>超清作品</label></div>${group('分辨率','resolutions',['1K','1.5K','2K','4K','8K'])}${group('比例','ratios',ratios.filter(r=>r!=='智能'))}</section>`;}
actions['asset-filter-panel']=()=>{assetPanel=assetPanel==='filters'?'':'filters';renderAssets();};actions['asset-sort']=()=>{assetSort=assetSort==='newest'?'oldest':'newest';renderAssets();};actions['clear-filters']=()=>{assetAdvanced={liked:false,upscaled:false,resolutions:[],ratios:[]};assetSearch='';assetFilter='all';renderAssets();};actions['toggle-bulk']=()=>{bulkMode=!bulkMode;selectedAssets.clear();renderAssets();};actions['clear-selection']=()=>{selectedAssets.clear();renderAssets();};
actions['bulk-like']=()=>{state.records.filter(r=>selectedAssets.has(r.id)).forEach(r=>r.liked=true);save();renderAssets();toast('所选作品已收藏');};
actions['bulk-delete']=()=>modal('删除所选作品？',`<p>将删除 ${selectedAssets.size} 件本地作品。对话中的相应作品也将移除。</p>`,`<button class="secondary-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="confirm-bulk-delete">删除作品</button>`);
actions['confirm-bulk-delete']=()=>{state.records=state.records.filter(r=>!selectedAssets.has(r.id));selectedAssets.clear();save();closeModal();renderAssets();toast('所选作品已删除');};
async function assetBlob(r){if(r.blobKey){const blob=await getBlob(r.blobKey);if(!blob)throw Error('本地素材不可用');return blob;}if(['audio','music'].includes(r.mode))return wav();const response=await fetch(r.src);if(!response.ok)throw Error('素材读取失败');return response.blob();}
actions['bulk-download']=async()=>{const button=$('[data-action="bulk-download"]');button.disabled=true;button.textContent='正在打包…';try{const files=[];for(const [i,r] of state.records.filter(r=>selectedAssets.has(r.id)).entries()){const blob=await assetBlob(r),ext=blob.type.split('/')[1]?.split(';')[0]||'bin';files.push({name:`${i+1}-${r.prompt.replace(/[\\/:*?"<>|]/g,'').slice(0,22)}.${ext}`,blob});}previewBlob(await StudioUtils.zipStore(files),'Safillu-作品合集.zip');toast('作品已打包为 ZIP');}catch(error){toast(error.message);}finally{renderAssets();}};
download=async function(id){const r=findRecord(id);try{const blob=await assetBlob(r),ext=({'image/jpeg':'jpg','image/png':'png','audio/wav':'wav','video/mp4':'mp4','audio/mpeg':'mp3','application/pdf':'pdf'})[blob.type]||r.prompt.split('.').at(-1)||'bin';previewBlob(blob,`Safillu-${r.prompt.replace(/[\\/:*?"<>|]/g,'').slice(0,25)}.${ext}`);toast(!r.upload&&['video','avatar','motion'].includes(r.mode)?'已下载动态演示的原始图片':'开始下载素材');}catch(error){toast(error.message);}};actions.download=el=>download(el.dataset.id);
rename=function(id){closeModal();editingSession=id;const row=$$('[data-session]').find(x=>x.dataset.session===id);if(!row)return;$('.session-title',row).innerHTML=`<input class="inline-rename" data-rename-id="${id}" aria-label="对话名称" maxlength="28" value="${esc(state.sessions.find(s=>s.id===id).title)}">`;const input=$('.inline-rename',row);input.focus();input.select();};
function commitRename(input,cancel=false){if(editingSession!==input.dataset.renameId)return;const s=state.sessions.find(s=>s.id===editingSession);if(!cancel&&input.value.trim())s.title=input.value.trim();editingSession=null;save();renderSessions();if(page==='create')$('#session-name').innerHTML=esc(session().title)+icon('chevron');}
sessionOptions=function(id){const s=state.sessions.find(s=>s.id===id);const row=$$('[data-session]').find(x=>x.dataset.session===id),box=row.getBoundingClientRect();closeMenu();$('#session-context')?.remove();const pop=document.createElement('div');pop.id='session-context';pop.className='session-context';pop.style.top=Math.min(innerHeight-145,box.top)+'px';pop.style.left=Math.min(innerWidth-190,box.right+8)+'px';pop.innerHTML=`<button class="menu-item" data-action="pin" data-id="${id}">${icon('spark')}${s.pinned?'取消置顶':'置顶'}</button><button class="menu-item" data-action="rename" data-id="${id}">${icon('edit')}重命名</button>${id!=='default'?`<button class="menu-item danger" data-action="delete-session" data-id="${id}">${icon('close')}删除</button>`:''}`;document.body.append(pop);};
const oldPin=actions.pin;actions.pin=el=>{oldPin(el);$('#session-context')?.remove();};
actions['confirm-delete-session']=el=>{if(el.dataset.id==='default'){toast('默认创作不能删除');return;}if(pending?.session===el.dataset.id){toast('请等待当前任务完成');return;}state.sessions=state.sessions.filter(s=>s.id!==el.dataset.id);if(state.current===el.dataset.id)state.current=state.sessions[0].id;save();closeModal();render();toast('已删除对话，作品保留在资产中');};
const oldRenderSessions=renderSessions;renderSessions=function(search=''){oldRenderSessions(search);$$('.inline-rename').forEach(x=>x.addEventListener('blur',()=>commitRename(x)));};
preview=function(id){const r=findRecord(id);if(!r)return;if(['music','audio'].includes(r.mode)){if(r.upload){modal('音频预览',`<h3>${esc(r.prompt)}</h3><audio class="audio-preview" controls src="${esc(r.src)}"></audio>`,actionBtn('download','下载','download',id));}else oldPreview(id);return;}if(r.mode==='document'){modal('文档预览',`<iframe class="document-preview" title="${esc(r.prompt)}" src="${esc(r.src)}"></iframe>`,actionBtn('download','下载文档','download',id),true);return;}
 const candidates=page==='assets'?getAssets():page==='explore'?exploreItems:state.records.filter(x=>x.session===state.current&&!x.deleted),list=candidates.some(x=>x.id===id)?candidates:[r,...candidates];previewIndex={list:list.map(x=>x.id),id};
 modal('作品预览',`<div class="detail-layout"><div class="detail-visual"><div class="detail-image-stage" id="detail-image-stage">${r.upload&&r.mode==='video'?`<video controls src="${esc(r.src)}"></video>`:`<img id="detail-image" src="${esc(r.src)}" alt="${esc(r.prompt)}" style="filter:${esc(r.filter||'none')}">`}</div><div class="image-navigation"><button class="icon-btn" data-action="preview-prev" title="上一个">←</button><span>${list.findIndex(x=>x.id===id)+1} / ${list.length}</span><button class="icon-btn" data-action="preview-next" title="下一个">→</button><label>缩放 <input id="preview-zoom" type="range" min="50" max="200" value="100" aria-label="预览缩放"></label></div></div><aside class="detail-sidebar"><div class="detail-actions">${actionBtn('download','下载','download',id)}${iconBtn('like','heart','收藏',id,r.liked?'liked':'')}<button class="icon-btn" data-action="record-options" data-id="${id}" aria-label="更多操作">···</button></div><span class="section-label">${r.upload?(r.cloud?'上传素材':'本地素材'):'图片提示词'}</span><p class="detail-prompt">${esc(r.prompt)}</p><div class="detail-pills"><span>${esc(r.model)}</span><span>${esc(r.ratio||'原始')}</span><span>${esc(r.resolution||'2K')}</span></div><button class="subtle-button" data-action="details" data-id="${id}">详细信息 ⓘ</button><div class="detail-edit-grid">${[['reedit','重新编辑'],['use-asset','用作参考图'],['copy-prompt','复制描述'],['create-subject-from','创建主体']].map(([a,t])=>`<button class="secondary-btn" data-action="${a}" data-id="${id}">${t}</button>`).join('')}</div><div class="section-label">创作工具</div><div class="detail-edit-grid">${['智能超清','智能改图','局部重绘','抠图','扩图','消除笔'].map(t=>`<button class="secondary-btn" data-action="edit-tool" data-tool="${t}" data-id="${id}">${t}</button>`).join('')}</div><p class="helper">工具提供前端配置与编辑草稿，未接入真实 AI 处理。动态作品使用示例图片。</p>${r.editDraft?`<p class="saved-draft">已保存：${esc(r.editDraft.tool)}配置</p>`:''}</aside></div>`,'',true);$('.modal').classList.add('art-detail-modal');};
actions.preview=el=>preview(el.dataset.id);
closeModal=function(){if('speechSynthesis'in window)speechSynthesis.cancel();oldCloseModal();};actions['close-modal']=closeModal;
actions['preview-prev']=()=>stepPreview(-1);actions['preview-next']=()=>stepPreview(1);
function stepPreview(delta){const {list,id}=previewIndex,index=list.indexOf(id),next=(index+delta+list.length)%list.length;preview(list[next]);}
actions['record-options']=el=>{const r=findRecord(el.dataset.id);modal('作品操作',`<p>${esc(r.prompt.slice(0,65))}</p>${[['copy-prompt','复制描述','edit'],['use-asset','用作参考图','image'],['create-subject-from','创建主体','person'],['delete-record','删除作品','close']].filter(([a])=>record(r.id)||a!=='delete-record').map(([action,label,svg])=>`<button class="menu-item" data-action="${action}" data-id="${r.id}">${icon(svg)}${label}</button>`).join('')}`);};
actions['create-subject-from']=el=>{const r=findRecord(el.dataset.id);modal('保存为主体',`<img class="subject-save-preview" src="${esc(r.src)}" alt=""><p>给角色起一个名字，下次使用 @ 即可引用。</p><input id="subject-from-name" aria-label="主体名称" placeholder="输入主体名称" maxlength="20">`,`<button class="primary-btn" data-action="save-subject-from" data-id="${r.id}">保存主体</button>`);};
actions['save-subject-from']=el=>{const name=$('#subject-from-name').value.trim();if(!name){toast('请输入主体名称');return;}const r=findRecord(el.dataset.id);state.subjects.push({id:uid(),name,src:r.src,blobKey:r.blobKey});save();closeModal();toast('主体已保存，可在创作栏引用');};
actions['edit-tool']=el=>{const r=findRecord(el.dataset.id),tool=el.dataset.tool;modal(tool,`<div class="local-edit-stage"><img src="${esc(r.src)}" alt="${esc(r.prompt)}"><canvas id="edit-mask" aria-label="涂抹编辑区域"></canvas></div><p class="helper">${['局部重绘','消除笔','抠图'].includes(tool)?'拖动鼠标涂抹需要处理的区域。':'设置编辑参数，保存到此作品的编辑草稿。'}本期仅提供前端配置，不运行 AI 处理。</p><label class="edit-setting">${tool==='智能超清'?'目标分辨率':'处理强度'}${tool==='智能超清'?'<select id="edit-setting" aria-label="目标分辨率"><option>2K</option><option selected>4K</option><option>8K</option></select>':'<input id="edit-setting" type="range" min="0" max="100" value="50" aria-label="处理强度">'}</label><textarea id="edit-instruction" placeholder="描述你想调整的内容…" aria-label="编辑描述"></textarea>`,`<button class="secondary-btn" data-action="clear-mask">清空涂抹</button><button class="primary-btn" data-action="save-edit-draft" data-id="${r.id}" data-tool="${tool}">保存编辑草稿</button>`,true);
 const canvas=$('#edit-mask'),rect=canvas.getBoundingClientRect();canvas.width=Math.round(rect.width*devicePixelRatio);canvas.height=Math.round(rect.height*devicePixelRatio);const ctx=canvas.getContext('2d');ctx.strokeStyle='#b8a0faaa';ctx.lineWidth=30*devicePixelRatio;ctx.lineCap='round';let drawing=false;const point=e=>{const b=canvas.getBoundingClientRect();return [(e.clientX-b.left)*canvas.width/b.width,(e.clientY-b.top)*canvas.height/b.height];};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke();}};canvas.onpointerup=()=>drawing=false;};
actions['clear-mask']=()=>{const c=$('#edit-mask');c?.getContext('2d').clearRect(0,0,c.width,c.height);};
actions['save-edit-draft']=el=>{const r=record(el.dataset.id);if(!r){toast('请先把示例作品用于创作后再保存编辑草稿');return;}r.editDraft={tool:el.dataset.tool,value:$('#edit-setting').value,instruction:$('#edit-instruction').value,mask:$('#edit-mask').toDataURL(),created:Date.now()};save();closeModal();toast('编辑配置与涂抹区域已保存到本地');};
reedit=function(id,notify=true){oldReedit(id,notify);const r=record(id);for(const key of ['attachments','voice','audioMode','referenceMode','musicSmart','musicSeconds','videoSeconds','spoken','actionDescription','motionTemplate'])if(r[key]!==undefined)draft()[key]=structuredClone(r[key]);if(!observedModels[draft().mode].includes(draft().model))draft().model=observedModels[draft().mode][0];save();syncComposer();};actions.reedit=el=>reedit(el.dataset.id);actions.regenerate=el=>{reedit(el.dataset.id,false);generate();};
useAsset=function(id){const r=findRecord(id),category=StudioUtils.category(r);closeModal();navigate('create');if(category==='document'){toast('文档可以预览和下载，暂不支持用作生成参考');return;}if(category!=='image'&&draft().mode!=='video')setMode(category==='audio'?'audio':'video');if(category==='image')draft().refs.push({src:r.src,name:r.prompt,blobKey:r.blobKey});else draft().attachments.push({src:r.src,name:r.prompt,blobKey:r.blobKey,type:r.mime||(category==='audio'?'audio/wav':'video/mp4'),slot:'reference'});if(r.fullPrompt){draft().prompt=r.fullPrompt;draft().mode=r.mode;draft().model=r.model;}save();syncComposer();toast('已添加到创作参考素材');};
document.addEventListener('click',e=>{const input=e.target.closest('.inline-rename');if(input){e.stopImmediatePropagation();return;}if($('#session-context')&&!e.target.closest('#session-context')&&!e.target.closest('[data-action="session-options"]'))$('#session-context').remove();const button=e.target.closest('[data-resolution],[data-draft-key],[data-voice-tab]');if(!button)return;e.stopImmediatePropagation();if(button.dataset.resolution){draft().resolution=button.dataset.resolution;save();syncComposer();openMenu=null;menu('format');}else if(button.dataset.draftKey){draft()[button.dataset.draftKey]=button.dataset.draftValue;save();syncComposer();closeMenu();}else{voiceTab=button.dataset.voiceTab;voiceLibrary();}},true);
document.addEventListener('keydown',e=>{if(e.target.matches('.inline-rename')){e.stopImmediatePropagation();if(e.key==='Enter'){e.preventDefault();commitRename(e.target);}if(e.key==='Escape'){e.preventDefault();commitRename(e.target,true);}}else if(e.target.matches('[role="button"][data-action="preview"]')&&['Enter',' '].includes(e.key)){e.preventDefault();preview(e.target.dataset.id);}else if(e.key==='Escape')$('#session-context')?.remove();},true);
document.addEventListener('focusout',e=>{if(e.target.matches('.inline-rename'))commitRename(e.target);});
document.addEventListener('input',e=>{
 const t=e.target,d=normalizeDraft(draft());
 if(t.id==='prompt')updateReady();
 if(t.id==='spoken'||t.id==='action-description'){d[t.id==='spoken'?'spoken':'actionDescription']=t.value;save();updateReady();}
 if(['duration-range','duration-number'].includes(t.id)){
  const min=d.mode==='music'?30:4,max=d.mode==='music'?360:15;let value=Number(t.value);
  if(!Number.isFinite(value)||!t.value)return;
  value=Math.round(Math.min(max,Math.max(min,value)));d[d.mode==='music'?'musicSeconds':'videoSeconds']=value;
  $('#duration-value').textContent=value;
  if(t.id==='duration-range')$('#duration-number').value=value;else $('#duration-range').value=value;
  const durationButton=$('#composer [data-menu="duration"]');
  if(durationButton)durationButton.textContent=d.mode==='music'&&d.musicSmart?'智能时长':value+'s';
  save();
 }
 if(t.id==='preview-zoom'&&$('#detail-image'))$('#detail-image').style.transform=`scale(${Number(t.value)/100})`;
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='music-smart'){draft().musicSmart=t.checked;save();syncComposer();}if(['duration-range','duration-number'].includes(t.id)){syncComposer();}if(t.dataset.voiceFilter){const key=t.dataset.voiceFilter;if(key==='gender')voiceGender=t.value;if(key==='age')voiceAge=t.value;if(key==='language')voiceLanguage=t.value;if(key==='trait')voiceTrait=t.value;voiceLibrary();}if(t.dataset.assetAdvanced){const key=t.dataset.assetAdvanced;assetAdvanced[key]=t.checked?[...assetAdvanced[key],t.value]:assetAdvanced[key].filter(x=>x!==t.value);renderAssets();}if(t.dataset.assetFlag){assetAdvanced[t.dataset.assetFlag]=t.checked;renderAssets();}if(t.dataset.selectAsset){t.checked?selectedAssets.add(t.dataset.selectAsset):selectedAssets.delete(t.dataset.selectAsset);renderAssets();}if(t.id==='select-all-assets'){for(const r of getAssets())t.checked?selectedAssets.add(r.id):selectedAssets.delete(r.id);renderAssets();}});
document.addEventListener('click',e=>{if(e.target.closest('#popover [data-ratio]')){const ratio=e.target.closest('[data-ratio]').dataset.ratio;if(ratio==='智能')draft().ratio='智能';}});
// Browser-local drop handling uses the same storage and validation as the picker.
$('#composer').addEventListener('drop',e=>{e.preventDefault();e.stopImmediatePropagation();$('#composer').style.borderColor='';if(e.dataTransfer.files.length){uploadKind='reference';referenceSlot='reference';mediaInput.files=e.dataTransfer.files;mediaInput.dispatchEvent(new Event('change'));}},true);
actions['rename-current']=()=>rename(state.current);actions.rename=el=>rename(el.dataset.id);actions['session-options']=el=>sessionOptions(el.dataset.id);
// Avoid account/payment affordances: only a local workspace and simulated usage remain.
$('.credit-label').textContent='演示积分';
$('#composer .composer-caption')?.remove();
